public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        long D = Long.parseLong(st.nextToken());
        long A = Long.parseLong(st.nextToken());

        long[][] monsters = new long[N][2];
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            monsters[i][0] = Long.parseLong(st.nextToken()); // X
            monsters[i][1] = Long.parseLong(st.nextToken()); // H
        }

        Arrays.sort(monsters, (a, b) -> Long.compare(a[0], b[0]));

        // Queue stores [expiry_x, total_damage]
        // expiry_x = X_i + 2D where X_i is the monster position when bomb was placed
        Deque<long[]> queue = new ArrayDeque<>();
        long totalDamage = 0;
        long bombs = 0;

        for (int i = 0; i < N; i++) {
            long x = monsters[i][0];
            long h = monsters[i][1];

            // Remove expired bombs
            while (!queue.isEmpty() && queue.peekFirst()[0] < x) {
                totalDamage -= queue.peekFirst()[1];
                queue.pollFirst();
            }

            // Check if current monster is already dead
            if (totalDamage >= h) continue;

            // Need more bombs
            long needed = (h - totalDamage + A - 1) / A;
            bombs += needed;
            long damage = needed * A;
            totalDamage += damage;
            // Bomb placed at x + D, covers [x, x + 2D]
            long expiry = x + 2 * D;
            queue.addLast(new long[]{expiry, damage});
        }

        System.out.println(bombs);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Monster implements Comparable<Monster> {
        long x, h;

        Monster(long x, long h) {
            this.x = x;
            this.h = h;
        }

        @Override
        public int compareTo(Monster o) {
            return Long.compare(this.x, o.x);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long D = fs.nextLong();
        long A = fs.nextLong();

        Monster[] monsters = new Monster[N];
        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            long h = fs.nextLong();
            monsters[i] = new Monster(x, h);
        }

        Arrays.sort(monsters);

        long[] xs = new long[N];
        long[] hs = new long[N];
        for (int i = 0; i < N; i++) {
            xs[i] = monsters[i].x;
            hs[i] = monsters[i].h;
        }

        long[] diff = new long[N + 1];
        long activeDamage = 0;
        long answer = 0;
        int r = 0;

        for (int i = 0; i < N; i++) {
            activeDamage += diff[i];

            long remaining = hs[i] - activeDamage;
            if (remaining <= 0) continue;

            long bombs = (remaining + A - 1) / A;
            answer += bombs;
            long addedDamage = bombs * A;
            activeDamage += addedDamage;

            long reach = xs[i] + 2L * D;
            while (r < N && xs[r] <= reach) r++;

            diff[r] -= addedDamage;
        }

        System.out.println(answer);
    }
}
